mkdir -p fixtures/ws tool/codegen && cat > /tmp/ws-capture.mjs <<'EOF'
import { WebSocket } from 'ws';
const fs = await import('node:fs');
fs.mkdirSync('fixtures/ws', { recursive: true });
const mux = fs.createWriteStream('fixtures/ws/mux-frames.jsonl');
const host = fs.createWriteStream('fixtures/ws/host-frames.jsonl');
function tap(name, ws, out) {
  ws.on('message', (data) => { out.write(JSON.stringify({ capturedAt: Date.now(), frame: JSON.parse(data.toString()) }) + '\n'); });
  ws.on('error', (e) => console.error(name, 'ERR', e.message));
  ws.on('close', (c, r) => console.log(name, 'closed', c, r.toString().slice(0,80)));
}
const a = new WebSocket('ws://127.0.0.1:3080/api/events.mux');
tap('mux', a, mux);
const b = new WebSocket('ws://127.0.0.1:3080/api/events.host');
tap('host', b, host);
setTimeout(() => { a.close(); b.close(); setTimeout(() => { mux.end(); host.end(); console.log('capture done'); process.exit(0); }, 500); }, 12000);
EOF
WS=$(node -e "try{console.log(require.resolve('ws'))}catch{console.log('')}")
if [ -n "$WS" ]; then NODE_PATH=$(dirname $(dirname $WS)) node /tmp/ws-capture.mjs; else node --input-type=module -e "import('ws').then(()=>console.log('ws resolvable')).catch(e=>{console.log('NO_WS',e.message);process.exit(3)})"; fi; echo EXIT=$?
